import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(Arrays.asList(5, 1, 8, 3, 2));
        while (!list.isEmpty()) {
            int maxIndex = 0;
            for (int i = 1; i < list.size(); i++) {
                if (list.get(i) > list.get(maxIndex)) {
                    maxIndex = i;
                }
            }
            System.out.print(list.remove(maxIndex) + " ");
        }
        System.out.println();
    }
}

